  regra:'O art. 11 diz que o tratamento de dados sensíveis {0|somente poderá ocorrer} nas hipóteses que enumera; o {1|legítimo interesse} do controlador está no art. 7º, IX, rol dos dados pessoais, não no {2|art. 11}.',
  pontos:[{ico:'📋',t:'Somente nas hipóteses',d:'o art. 11 usa a expressão "somente poderá ocorrer"'},{ico:'🤝',t:'Legítimo interesse',d:'consta do art. 7º, IX'},{ico:'🛡️',t:'Art. 11',d:'consentimento (I) e hipóteses do inciso II'}],
