  regra:'O tratamento de dado sensível ocorre {0|sem fornecimento de consentimento} do titular quando for {1|indispensável} para o {2|cumprimento de obrigação legal ou regulatória} pelo {3|controlador}.',
  pontos:[{ico:'🚪',t:'Sem consentimento',d:'inciso II do art. 11'},{ico:'🔒',t:'Indispensável',d:'requisito de todas as alíneas do inciso II'},{ico:'📜',t:'Legal ou regulatória',d:'a obrigação pode vir de lei ou de regulamento'},{ico:'🧑‍💼',t:'Controlador',d:'é quem cumpre a obrigação'}],
