  regra:'O consentimento {0|específico e destacado} é o inciso I; o inciso II prevê tratamento {1|sem fornecimento de consentimento} em hipóteses como {2|obrigação legal} e {3|estudos por órgão de pesquisa}.',
  pontos:[{ico:'✍️',t:'Específico e destacado',d:'forma do consentimento do inciso I'},{ico:'🚪',t:'Sem consentimento',d:'inciso II, alíneas "a" a "g"'},{ico:'📜',t:'Obrigação legal',d:'alínea "a"'},{ico:'🔬',t:'Órgão de pesquisa',d:'alínea "c"'}],
