  regra:'{0|Pseudonimização} é o tratamento pelo qual o dado perde a possibilidade de associação a um indivíduo, {1|senão pelo uso de informação adicional} mantida {2|separadamente pelo controlador} em ambiente {3|controlado e seguro}.',
  pontos:[{ico:'🎭',t:'Pseudonimização',d:'definida no § 4º do art. 13'},{ico:'🧩',t:'Informação adicional',d:'permite reassociar o dado ao indivíduo'},{ico:'🗄️',t:'Guarda separada',d:'mantida à parte pelo controlador'},{ico:'🔐',t:'Ambiente seguro',d:'controlado e seguro'}],
